"use client";

import { useEffect, useMemo, useState } from "react";

type Deal = {
  id: number; customer_name: string; contact_person: string; contact: string; email: string;
  customer_type: string; province: string; region: string; zone: string; quotation_no: string;
  order_no: string; invoice_no: string; value: number; potential_value: number; gp_percent: number;
  probability: number; stage: string; assigned_to: string; coordinator: string; monthly_target: number;
  last_visit: string; next_follow_up: string; next_action: string; quote_date: string;
  quote_follow_up_date: string; quote_status: string; confirmed_date: string;
  delivery_status: string; delivery_eta: string; delivered_date: string; delivery_notes: string;
  customer_number: string; application_status: string; registered_name: string; registration_number: string;
  vat_number: string; nature_of_business: string; years_in_business: number; branch_count: number;
  head_office_address: string; postal_code: string; website: string; legal_entity: string;
  owner1_name: string; owner1_id: string; owner1_position: string; owner1_mobile: string;
  owner2_name: string; owner2_id: string; owner2_position: string; owner2_mobile: string;
  purchasing_contact_name: string; purchasing_contact_mobile: string; purchasing_contact_email: string;
  accounts_contact_name: string; accounts_contact_mobile: string; accounts_contact_email: string;
  delivery_address: string; delivery_contact: string; delivery_contact_mobile: string; receiving_hours: string;
  delivery_requirements: string; product_categories: string; average_monthly_spend: number;
  ordering_method: string; ordering_frequency: string; payment_terms: string; credit_requested: number;
  price_group: string; declaration_accepted: number; application_submitted_at: string;
  approved_by: string; approved_at: string; approval_comments: string;
  created_at: string; visit_count?: number; document_count?: number;
};
type Visit = { id: number; opportunity_id: number; customer_name: string; assigned_to: string; visit_date: string; visit_type: string; update_type?: string; contact_person: string; outcome: string; notes: string; next_follow_up: string; scheduled_time?: string; purpose?: string; visit_status?: string; area?: string; visit_address?: string; created_by: string; quotation_no?: string; order_no?: string; invoice_no?: string; stage?: string };
type Settings = { base_target: number; base_gp_threshold: number; accelerator_gp_threshold: number; rep_base_rate: number; rep_accelerator_rate: number; coordinator_rate: number; head_rate: number };
type TeamMember = { name: string; email: string; role: string; department: string };
type CustomerDocument = { id: number; document_type: string; name: string; mime_type: string; size: number; uploaded_by: string; created_at: string };
type Tab = "dashboard" | "customers" | "visits" | "pipeline" | "quotes" | "deliveries" | "performance";

const stages = ["Lead", "Qualified", "Visit Completed", "Quotation", "Follow-up", "Negotiation", "Confirmed Order", "Invoiced", "Delivery Planned", "Delivered", "Lost"];
const stageProgress: Record<string, number> = { Lead: 10, Qualified: 20, "Visit Completed": 30, Quotation: 45, "Follow-up": 55, Negotiation: 65, "Confirmed Order": 75, Invoiced: 82, "Delivery Planned": 90, Delivered: 100, Lost: 0 };
const customerTypes = ["Small", "Medium", "Large"];
const productCategories = ["Timber", "Cement", "Paint", "Waterproofing", "PVC Pipes & Fittings", "Plumbing", "Sanware", "Doors & Frames", "Hardware", "Tools", "Electrical", "Building Materials", "Adhesives", "Roofing"];
const documentTypes = ["Company Registration Documents", "VAT Registration Certificate", "Owner / Director ID", "Proof of Business Address", "Tax / Business Information", "Store Photo", "Other Supporting Document"];
const defaults: Settings = { base_target: 1000000, base_gp_threshold: 10, accelerator_gp_threshold: 15, rep_base_rate: 5, rep_accelerator_rate: 6, coordinator_rate: 2, head_rate: 2 };
const money = (n: number) => new Intl.NumberFormat("en-ZA", { style: "currency", currency: "ZAR", maximumFractionDigits: 0 }).format(n || 0);
const today = () => new Date().toISOString().slice(0, 10);
const currentTime = () => new Date().toTimeString().slice(0, 5);
const ageInDays = (date: string) => date ? Math.floor((Date.now() - new Date(`${date}T00:00:00`).getTime()) / 86400000) : 0;
const quoteOverdue = (deal: Deal) => Boolean(deal.quotation_no && deal.quote_date && !["Accepted", "Declined"].includes(deal.quote_status) && ageInDays(deal.quote_follow_up_date || deal.quote_date) >= 2);
const deliveryOverdue = (deal: Deal) => Boolean((deal.order_no || deal.invoice_no) && deal.confirmed_date && !["Dispatched", "Delivered"].includes(deal.delivery_status) && ageInDays(deal.confirmed_date) >= 3);
const blankDeal = () => ({ customer_name: "", contact_person: "", contact: "", email: "", customer_type: "Small", province: "Gauteng", region: "Central", zone: "", quotation_no: "", order_no: "", invoice_no: "", value: "", potential_value: "", gp_percent: "15", probability: "10", stage: "Lead", assigned_to: "", coordinator: "", monthly_target: "1000000", last_visit: "", next_follow_up: "", next_action: "", quote_date: "", quote_follow_up_date: "", quote_status: "Pending", confirmed_date: "", delivery_status: "Not planned", delivery_eta: "", delivered_date: "", delivery_notes: "", customer_number: "", application_status: "Pending approval", registered_name: "", registration_number: "", vat_number: "", nature_of_business: "Hardware Store", years_in_business: "", branch_count: "1", head_office_address: "", postal_code: "", website: "", legal_entity: "(Pty) Ltd", owner1_name: "", owner1_id: "", owner1_position: "", owner1_mobile: "", owner2_name: "", owner2_id: "", owner2_position: "", owner2_mobile: "", purchasing_contact_name: "", purchasing_contact_mobile: "", purchasing_contact_email: "", accounts_contact_name: "", accounts_contact_mobile: "", accounts_contact_email: "", delivery_address: "", delivery_contact: "", delivery_contact_mobile: "", receiving_hours: "", delivery_requirements: "", product_categories: "[]", average_monthly_spend: "", ordering_method: "WhatsApp / Email", ordering_frequency: "Weekly", payment_terms: "COD / EFT Before Dispatch", credit_requested: "0", price_group: "Standard Wholesale", declaration_accepted: "0", approval_comments: "" });
const blankVisit = () => ({ opportunity_id: "", visit_date: today(), visit_type: "In person", update_type: "Customer visit", contact_person: "", outcome: "", notes: "", next_follow_up: "", scheduled_time: "09:00", purpose: "Relationship visit", visit_status: "Planned", area: "", visit_address: "", stage: "Lead", potential_value: "", probability: "10", quotation_no: "", quote_status: "Pending", order_no: "", invoice_no: "", value: "", delivery_status: "Not planned", delivery_eta: "" });

export default function WholesaleCrm() {
  const [deals, setDeals] = useState<Deal[]>([]), [visits, setVisits] = useState<Visit[]>([]),
    [settings, setSettings] = useState<Settings>(defaults), [tab, setTab] = useState<Tab>("dashboard"),
    [openDeal, setOpenDeal] = useState(false), [openVisit, setOpenVisit] = useState(false),
    [settingsOpen, setSettingsOpen] = useState(false), [editing, setEditing] = useState<Deal | null>(null),
    [dealDraft, setDealDraft] = useState(blankDeal()), [visitDraft, setVisitDraft] = useState(blankVisit()),
    [members, setMembers] = useState<TeamMember[]>([]), [wholesaleHead, setWholesaleHead] = useState("Hub Owner"),
    [enrolmentStep, setEnrolmentStep] = useState(1), [customerFiles, setCustomerFiles] = useState<Array<{ file: File; type: string }>>([]),
    [uploadDocumentType, setUploadDocumentType] = useState(documentTypes[0]),
    [existingDocuments, setExistingDocuments] = useState<CustomerDocument[]>([]),
    [approvalDeal, setApprovalDeal] = useState<Deal | null>(null), [approvalComments, setApprovalComments] = useState(""),
    [canApprove, setCanApprove] = useState(false), [editingVisit, setEditingVisit] = useState<Visit | null>(null),
    [currentUserName, setCurrentUserName] = useState(""), [fieldVisitApplication, setFieldVisitApplication] = useState(false),
    [visitRepFilter, setVisitRepFilter] = useState("All reps"), [visitStatusFilter, setVisitStatusFilter] = useState("All visits"),
    [busy, setBusy] = useState(true), [saving, setSaving] = useState(false), [error, setError] = useState(""),
    [success, setSuccess] = useState("");
  const load = async () => {
    setBusy(true);
    try {
      const [a, b, c, d] = await Promise.all([fetch("/api/wholesale"), fetch("/api/wholesale/visits"), fetch("/api/wholesale/commission"), fetch("/api/team")]);
      const [x, y, z, team] = await Promise.all([a.json(), b.json(), c.json(), d.json()]);
      if (a.ok) setDeals(x.opportunities || []); if (b.ok) setVisits(y.visits || []); if (c.ok) setSettings(z.settings || defaults);
      if (d.ok) {
        setMembers((team.members || []).filter((member: TeamMember) => member.name));
        setWholesaleHead(team.current_user?.name || "Hub Owner");
        setCurrentUserName(team.current_user?.name || "");
        setCanApprove(team.current_user?.role === "Owner / Admin");
      }
    } finally { setBusy(false); }
  };
  useEffect(() => { const timer = window.setTimeout(() => void load(), 0); return () => window.clearTimeout(timer); }, []);

  const startDeal = (deal?: Deal, fromFieldVisit = false) => {
    setEditing(deal || null); setError(""); setSuccess("");
    const nextDraft = deal ? Object.fromEntries(Object.entries(blankDeal()).map(([key]) => [key, String(deal[key as keyof Deal] ?? "")])) as ReturnType<typeof blankDeal> : blankDeal();
    if (fromFieldVisit && !deal) nextDraft.assigned_to = currentUserName;
    setDealDraft(nextDraft); setFieldVisitApplication(fromFieldVisit && !deal);
    setCustomerFiles([]); setExistingDocuments([]); setEnrolmentStep(1); setOpenDeal(true);
    if (deal) void fetch(`/api/wholesale/${deal.id}/documents`).then((response) => response.json()).then((data) => setExistingDocuments(data.documents || [])).catch(() => setExistingDocuments([]));
  };
  const saveDeal = async () => {
    if (!dealDraft.customer_name.trim()) return setError("Customer name is required.");
    setSaving(true); setError("");
    try {
      const payload = fieldVisitApplication && !editing ? { ...dealDraft, create_unplanned_visit: "1", field_visit_date: today(), field_visit_time: currentTime() } : dealDraft;
      const response = await fetch(editing ? `/api/wholesale/${editing.id}` : "/api/wholesale", { method: editing ? "PATCH" : "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(payload) });
      const data = await response.json().catch(() => ({}));
      if (!response.ok) throw new Error(data.error || "The CRM record could not be saved.");
      const customerId = editing?.id || data.opportunity?.id;
      for (const upload of customerFiles) {
        const form = new FormData(); form.append("file", upload.file); form.append("document_type", upload.type);
        const uploaded = await fetch(`/api/wholesale/${customerId}/documents`, { method: "POST", body: form });
        if (!uploaded.ok) throw new Error((await uploaded.json().catch(() => ({}))).error || `Could not upload ${upload.file.name}.`);
      }
      setOpenDeal(false); setFieldVisitApplication(false); await load();
      setSuccess(editing ? "Customer enrolment details updated." : fieldVisitApplication ? "Unplanned new-customer visit recorded and application submitted for approval." : "Customer application submitted for Head of Wholesale approval.");
    } catch (reason) { setError(reason instanceof Error ? reason.message : "The CRM record could not be saved."); }
    finally { setSaving(false); }
  };
  const startVisit = (deal?: Deal, updateType = "Customer visit", planned = false) => {
    setEditingVisit(null);
    setVisitDraft({ ...blankVisit(), opportunity_id: deal ? String(deal.id) : "", contact_person: deal?.contact_person || "", update_type: updateType, visit_status: planned || updateType === "Customer visit" ? "Planned" : "Completed", area: deal?.zone || deal?.region || "", visit_address: deal?.delivery_address || deal?.head_office_address || "", stage: deal?.stage || "Lead", potential_value: String(deal?.potential_value || ""), probability: String(deal?.probability || 10), quotation_no: deal?.quotation_no || "", quote_status: deal?.quote_status || "Pending", order_no: deal?.order_no || "", invoice_no: deal?.invoice_no || "", value: String(deal?.value || ""), delivery_status: deal?.delivery_status || "Not planned", delivery_eta: deal?.delivery_eta || "" });
    setError(""); setSuccess(""); setOpenVisit(true);
  };
  const completeVisit = (visit: Visit) => {
    setEditingVisit(visit);
    setVisitDraft({ ...blankVisit(), opportunity_id: String(visit.opportunity_id), visit_date: visit.visit_date, scheduled_time: visit.scheduled_time || "09:00", visit_type: visit.visit_type || "In person", update_type: "Customer visit", visit_status: "Completed", contact_person: visit.contact_person || "", purpose: visit.purpose || "Relationship visit", area: visit.area || "", visit_address: visit.visit_address || "", outcome: visit.outcome || "", notes: visit.notes || "", next_follow_up: visit.next_follow_up || "", stage: visit.stage || "Lead", potential_value: "", probability: "10", quotation_no: visit.quotation_no || "", quote_status: "Pending", order_no: visit.order_no || "", invoice_no: visit.invoice_no || "", value: "", delivery_status: "Not planned", delivery_eta: "" });
    setError(""); setOpenVisit(true);
  };
  const selectVisitCustomer = (value: string) => {
    const deal = deals.find((row) => row.id === Number(value));
    setVisitDraft((current) => ({
      ...current,
      opportunity_id: value,
      contact_person: deal?.contact_person || current.contact_person,
      area: deal?.zone || deal?.region || "",
      visit_address: deal?.delivery_address || deal?.head_office_address || "",
      stage: deal?.stage || current.stage,
      potential_value: String(deal?.potential_value || ""),
      probability: String(deal?.probability || 10),
      quotation_no: deal?.quotation_no || "",
      quote_status: deal?.quote_status || "Pending",
      order_no: deal?.order_no || "",
      invoice_no: deal?.invoice_no || "",
      value: String(deal?.value || ""),
      delivery_status: deal?.delivery_status || "Not planned",
      delivery_eta: deal?.delivery_eta || "",
    }));
  };
  const saveVisit = async () => {
    if (!visitDraft.opportunity_id || !visitDraft.visit_date) return setError("Select a customer and visit date.");
    setSaving(true); setError("");
    try {
      const response = await fetch(editingVisit ? `/api/wholesale/visits/${editingVisit.id}` : "/api/wholesale/visits", { method: editingVisit ? "PATCH" : "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(visitDraft) });
      const data = await response.json().catch(() => ({}));
      if (!response.ok) throw new Error(data.error || "The visit could not be saved.");
      setOpenVisit(false); setEditingVisit(null); await load(); setSuccess(visitDraft.visit_status === "Planned" ? "Rep visit added to the visit planner." : "Visit completed and customer activity updated everywhere.");
    } catch (reason) { setError(reason instanceof Error ? reason.message : "The visit could not be saved."); }
    finally { setSaving(false); }
  };
  const saveSettings = async () => {
    setSaving(true); await fetch("/api/wholesale/commission", { method: "PATCH", headers: { "content-type": "application/json" }, body: JSON.stringify(settings) });
    setSaving(false); setSettingsOpen(false); setSuccess("Commission settings saved.");
  };
  const approveCustomer = async (action: "Approve" | "Decline" | "Request changes") => {
    if (!approvalDeal) return;
    setSaving(true); setError("");
    try {
      const response = await fetch(`/api/wholesale/${approvalDeal.id}/approval`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ action, comments: approvalComments }) });
      const data = await response.json().catch(() => ({}));
      if (!response.ok) throw new Error(data.error || "The customer application could not be updated.");
      setApprovalDeal(null); setApprovalComments(""); await load();
      setSuccess(action === "Approve" ? `Customer approved and account ${data.customer_number} created.` : `Customer application marked: ${data.status}.`);
    } catch (reason) { setError(reason instanceof Error ? reason.message : "The customer application could not be updated."); }
    finally { setSaving(false); }
  };
  const startApproval = (deal: Deal) => {
    setApprovalDeal(deal); setApprovalComments(deal.approval_comments || ""); setExistingDocuments([]); setError("");
    void fetch(`/api/wholesale/${deal.id}/documents`).then((response) => response.json()).then((data) => setExistingDocuments(data.documents || [])).catch(() => setExistingDocuments([]));
  };

  const customers = useMemo(() => {
    const grouped = new Map<string, Deal[]>();
    for (const deal of deals) grouped.set(deal.customer_name.toLowerCase(), [...(grouped.get(deal.customer_name.toLowerCase()) || []), deal]);
    return Array.from(grouped.values()).map((rows) => ({ primary: rows[0], opportunities: rows.length, potential: rows.reduce((sum, row) => sum + Number(row.potential_value || row.value), 0), quotes: rows.filter((row) => row.quotation_no).length, orders: rows.filter((row) => row.order_no || row.invoice_no).length, visits: rows.reduce((sum, row) => sum + Number(row.visit_count || 0), 0) }));
  }, [deals]);
  const pendingCustomers = deals.filter((deal) => ["Pending approval", "Changes requested"].includes(deal.application_status || "Pending approval"));
  const filteredVisits = visits.filter((visit) => (visitRepFilter === "All reps" || visit.assigned_to === visitRepFilter) && (visitStatusFilter === "All visits" || (visit.visit_status || "Completed") === visitStatusFilter));
  const plannedVisits = filteredVisits.filter((visit) => (visit.visit_status || "Completed") === "Planned").sort((a, b) => `${a.visit_date}${a.scheduled_time || ""}`.localeCompare(`${b.visit_date}${b.scheduled_time || ""}`));
  const visitHistory = filteredVisits.filter((visit) => (visit.visit_status || "Completed") !== "Planned");
  const currentMonth = today().slice(0, 7), monthlyCompletedVisits = visits.filter((visit) => String(visit.update_type || "").toLowerCase().includes("visit") && (visit.visit_status || "Completed") === "Completed" && visit.visit_date.startsWith(currentMonth)).length,
    todayPlannedVisits = visits.filter((visit) => (visit.visit_status || "Completed") === "Planned" && visit.visit_date === today()).length,
    followUpsDue = deals.filter((deal) => deal.next_follow_up && deal.next_follow_up <= today()).length;
  const overdueQuotes = deals.filter(quoteOverdue), overdueDeliveries = deals.filter(deliveryOverdue),
    activeDeals = deals.filter((deal) => !["Lost", "Delivered"].includes(deal.stage)),
    pipelineValue = activeDeals.reduce((sum, deal) => sum + Number(deal.potential_value || deal.value), 0),
    confirmedValue = deals.filter((deal) => ["Confirmed Order", "Invoiced", "Delivery Planned", "Delivered"].includes(deal.stage) || deal.order_no || deal.invoice_no).reduce((sum, deal) => sum + Number(deal.value), 0),
    weightedPipeline = activeDeals.reduce((sum, deal) => sum + Number(deal.potential_value || deal.value) * Number(deal.probability || 0) / 100, 0);
  const performance = useMemo(() => Array.from(new Set(deals.map((deal) => deal.assigned_to || "Unassigned"))).map((rep) => {
    const rows = deals.filter((deal) => (deal.assigned_to || "Unassigned") === rep), won = rows.filter((deal) => deal.order_no || deal.invoice_no || ["Confirmed Order", "Invoiced", "Delivery Planned", "Delivered"].includes(deal.stage)),
      sales = won.reduce((sum, deal) => sum + Number(deal.value), 0), gp = won.reduce((sum, deal) => sum + Number(deal.value) * Number(deal.gp_percent) / 100, 0), gpp = sales ? gp / sales * 100 : 0,
      target = Number(rows.find((deal) => deal.monthly_target)?.monthly_target) || settings.base_target, eligible = sales >= target,
      rate = gpp >= settings.accelerator_gp_threshold ? settings.rep_accelerator_rate : gpp >= settings.base_gp_threshold ? settings.rep_base_rate : 0;
    return { rep, coordinator: rows.find((deal) => deal.coordinator)?.coordinator || "Unassigned", customers: new Set(rows.map((deal) => deal.customer_name)).size, visits: rows.reduce((sum, deal) => sum + Number(deal.visit_count || 0), 0), quotes: rows.filter((deal) => deal.quotation_no).length, orders: won.length, sales, gp, gpp, target, eligible, rate, repCommission: eligible ? gp * rate / 100 : 0, coordinatorCommission: eligible ? gp * settings.coordinator_rate / 100 : 0, headCommission: eligible ? gp * settings.head_rate / 100 : 0 };
  }), [deals, settings]);

  const progress = (deal: Deal) => <span className="crmProgress"><i style={{ width: `${stageProgress[deal.stage] ?? deal.probability ?? 0}%` }} /><small>{stageProgress[deal.stage] ?? deal.probability ?? 0}%</small></span>;
  const alertBadge = (kind: "quote" | "delivery", deal: Deal) => {
    const overdue = kind === "quote" ? quoteOverdue(deal) : deliveryOverdue(deal);
    return <em className={`crmAlert ${overdue ? "overdue" : "clear"}`}>{overdue ? `Overdue ${kind === "quote" ? "follow-up" : "dispatch"}` : "On track"}</em>;
  };
  const memberOptions = (current: string) => Array.from(new Set([current, ...members.map((member) => member.name)].filter(Boolean)));
  const selectedProducts = (() => { try { const parsed = JSON.parse(dealDraft.product_categories || "[]"); return Array.isArray(parsed) ? parsed as string[] : []; } catch { return []; } })();
  const toggleProduct = (product: string) => setDealDraft({ ...dealDraft, product_categories: JSON.stringify(selectedProducts.includes(product) ? selectedProducts.filter((item) => item !== product) : [...selectedProducts, product]) });

  return <>
    <div className="crmKpis wholesaleCrmKpis">
      <button onClick={() => setTab("customers")} className={pendingCustomers.length ? "attention" : ""}><small>Customer applications</small><b>{pendingCustomers.length}</b><em>Waiting for review or changes</em></button>
      <button onClick={() => setTab("pipeline")}><small>Active sales pipeline</small><b>{money(pipelineValue)}</b><em>{money(weightedPipeline)} weighted potential</em></button>
      <button onClick={() => setTab("quotes")} className={overdueQuotes.length ? "attention" : ""}><small>Quotes needing attention</small><b>{overdueQuotes.length}</b><em>Not followed up within 2 days</em></button>
      <button onClick={() => setTab("deliveries")} className={overdueDeliveries.length ? "attention" : ""}><small>Late order dispatches</small><b>{overdueDeliveries.length}</b><em>Not sent within 3 days</em></button>
      <button onClick={() => setTab("deliveries")}><small>Confirmed order value</small><b>{money(confirmedValue)}</b><em>Orders, invoices and deliveries</em></button>
    </div>
    {success && <div className="memberSuccess wholesaleSuccess">✓ {success}</div>}
    {error && !openDeal && !openVisit && <div className="formError">{error}</div>}
    <section className="panel crmPanel wholesaleCrmPanel">
      <div className="crmNav wholesaleCrmNav"><nav>
        {(["dashboard", "customers", "visits", "pipeline", "quotes", "deliveries", "performance"] as Tab[]).map((item) => <button key={item} className={tab === item ? "active" : ""} onClick={() => setTab(item)}>{({ dashboard: "CRM Dashboard", customers: "Customer Database", visits: "Client Visits", pipeline: "Sales Pipeline", quotes: "Quotes & Follow-ups", deliveries: "Orders & Deliveries", performance: "Targets & Commission" } as Record<Tab, string>)[item]}</button>)}
      </nav><div><button onClick={() => setSettingsOpen(true)}>Commission settings</button><button onClick={() => startVisit(undefined, "General follow-up")}>＋ Log update</button><button onClick={() => startVisit(undefined, "Customer visit", true)}>＋ Plan rep visit</button><button className="fieldVisitAction" onClick={() => startDeal(undefined, true)}>＋ Unplanned visit / new customer</button><button className="primary" onClick={() => startDeal()}>＋ New customer application</button></div></div>
      {busy ? <div className="loading">Loading wholesale CRM…</div> : tab === "dashboard" ? <div className="wholesaleDashboard">
        <section><header><span><h3>Quotes requiring follow-up</h3><small>Automatically flagged after two days</small></span><b>{overdueQuotes.length}</b></header>{!overdueQuotes.length ? <p className="crmAllClear">✓ All quotes are within follow-up time</p> : overdueQuotes.slice(0, 6).map((deal) => <button key={deal.id} onClick={() => startVisit(deal, "Quote follow-up")}><span><b>{deal.customer_name}</b><small>{deal.quotation_no} · {money(deal.potential_value || deal.value)}</small></span><em>{ageInDays(deal.quote_follow_up_date || deal.quote_date)} days</em></button>)}</section>
        <section><header><span><h3>Deliveries requiring action</h3><small>Confirmed orders not sent within three days</small></span><b>{overdueDeliveries.length}</b></header>{!overdueDeliveries.length ? <p className="crmAllClear">✓ All confirmed deliveries are on track</p> : overdueDeliveries.slice(0, 6).map((deal) => <button key={deal.id} onClick={() => startVisit(deal, "Order / delivery update")}><span><b>{deal.customer_name}</b><small>{deal.invoice_no || deal.order_no} · ETA {deal.delivery_eta || "not set"}</small></span><em>{ageInDays(deal.confirmed_date)} days</em></button>)}</section>
        <section className="wide"><header><span><h3>Pipeline progress</h3><small>Live sales potential by customer and stage</small></span><b>{activeDeals.length}</b></header><div className="crmPipelineCards">{activeDeals.slice(0, 8).map((deal) => <button key={deal.id} onClick={() => startVisit(deal, "General follow-up")}><span><b>{deal.customer_name}</b><small>{deal.stage} · {money(deal.potential_value || deal.value)}</small></span>{progress(deal)}</button>)}</div></section>
      </div> : tab === "customers" ? <div className="tablewrap"><table><thead><tr><th>Customer No.</th><th>Customer</th><th>Intake Status</th><th>Primary Contact</th><th>Location</th><th>Sales Team</th><th>Documents</th><th>Sales Potential</th><th>Next Follow-up</th><th>Actions</th></tr></thead><tbody>{customers.map(({ primary: deal, ...summary }) => <tr key={deal.id}><td><b className="customerNumber">{deal.customer_number || "Issued on approval"}</b></td><td><b>{deal.customer_name}</b><small>{deal.registered_name || deal.nature_of_business || deal.customer_type}</small></td><td><em className={`intakeStatus ${String(deal.application_status || "Pending approval").toLowerCase().replaceAll(" ", "-")}`}>{deal.application_status || "Pending approval"}</em><small>{deal.approval_comments || ""}</small></td><td>{deal.purchasing_contact_name || deal.contact_person || "—"}<small>{deal.purchasing_contact_mobile || deal.contact || deal.email || "No contact details"}</small></td><td>{deal.province}<small>{deal.region} · {deal.zone}</small></td><td>{deal.assigned_to || "Unassigned"}<small>{deal.coordinator || "No coordinator"}</small></td><td><b>{deal.document_count || 0}</b><small>documents / photos</small></td><td><b>{money(summary.potential)}</b></td><td>{deal.next_follow_up || "Not set"}</td><td><button className="crmEdit" onClick={() => startVisit(deal, "Customer visit", true)}>Plan visit</button><button className="crmTextAction" onClick={() => startVisit(deal, "General follow-up")}>Log update</button><button className="crmTextAction" onClick={() => startDeal(deal)}>View / edit</button>{canApprove && deal.application_status !== "Approved" && <button className="crmApprove" onClick={() => startApproval(deal)}>Review</button>}</td></tr>)}</tbody></table></div>
      : tab === "visits" ? <div className="visitWorkspace"><div className="visitPlannerToolbar"><span><h3>Rep Visit Planner</h3><p>Plan each rep&apos;s day by customer, area, time and purpose, then complete the visit from the same record.</p></span><label>Rep<select value={visitRepFilter} onChange={(event) => setVisitRepFilter(event.target.value)}><option>All reps</option>{Array.from(new Set(deals.map((deal) => deal.assigned_to).filter(Boolean))).map((rep) => <option key={rep}>{rep}</option>)}</select></label><label>View<select value={visitStatusFilter} onChange={(event) => setVisitStatusFilter(event.target.value)}>{["All visits", "Planned", "Completed", "Cancelled", "Rescheduled"].map((status) => <option key={status}>{status}</option>)}</select></label><button className="primary" onClick={() => startVisit(undefined, "Customer visit", true)}>＋ Schedule visit</button></div><div className="visitPlannerStats"><span><small>Today&apos;s planned visits</small><b>{todayPlannedVisits}</b></span><span><small>Completed this month</small><b>{monthlyCompletedVisits} / 150</b><i><em style={{ width: `${Math.min(100, monthlyCompletedVisits / 150 * 100)}%` }} /></i></span><span><small>Customer follow-ups due</small><b>{followUpsDue}</b></span></div><section className="plannedVisits"><header><span><h3>Upcoming Visits</h3><small>Rep itinerary and call plan</small></span><b>{plannedVisits.length}</b></header>{!plannedVisits.length ? <p className="crmAllClear">No planned visits in this view.</p> : <div className="tablewrap"><table><thead><tr><th>Date / Time</th><th>Rep</th><th>Customer</th><th>Area / Address</th><th>Visit Purpose</th><th>Contact</th><th>Action</th></tr></thead><tbody>{plannedVisits.map((visit) => <tr key={visit.id}><td><b>{visit.visit_date}</b><small>{visit.scheduled_time || "Time not set"}</small></td><td><b>{visit.assigned_to || "Unassigned"}</b></td><td><b>{visit.customer_name}</b></td><td>{visit.area || "—"}<small>{visit.visit_address || "Address not set"}</small></td><td>{visit.purpose || "Relationship visit"}</td><td>{visit.contact_person || "—"}</td><td><button className="crmEdit" onClick={() => completeVisit(visit)}>Complete visit</button></td></tr>)}</tbody></table></div>}</section><section className="visitHistory"><header><span><h3>Visit &amp; Contact History</h3><small>Completed visits, calls, quotes and order updates</small></span><b>{visitHistory.length}</b></header><div className="tablewrap"><table><thead><tr><th>Date</th><th>Customer</th><th>Rep</th><th>Activity</th><th>Purpose / Outcome</th><th>Linked Quote / Order</th><th>Next Follow-up</th><th>Logged By</th></tr></thead><tbody>{visitHistory.map((visit) => <tr key={visit.id}><td><b>{visit.visit_date}</b><small>{visit.scheduled_time || ""}</small></td><td><b>{visit.customer_name}</b><small>{visit.area || visit.contact_person || "—"}</small></td><td>{visit.assigned_to || "Unassigned"}</td><td><b>{visit.update_type || "General follow-up"}</b><small>{visit.visit_type} · {visit.visit_status || "Completed"}</small></td><td>{visit.purpose || visit.outcome || "—"}<small>{visit.outcome || visit.notes || ""}</small></td><td>{visit.quotation_no || visit.order_no || visit.invoice_no || "General CRM update"}<small>{visit.stage || ""}</small></td><td>{visit.next_follow_up || "Not set"}</td><td>{visit.created_by || "—"}</td></tr>)}</tbody></table></div></section></div>
      : tab === "pipeline" ? <div className="tablewrap"><table><thead><tr><th>Customer / Opportunity</th><th>Rep</th><th>Potential</th><th>Weighted Value</th><th>Progress</th><th>Next Action</th><th>Follow-up</th><th>Actions</th></tr></thead><tbody>{deals.filter((deal) => deal.stage !== "Lost").map((deal) => <tr key={deal.id}><td><b>{deal.customer_name}</b><small>{deal.customer_type} · {deal.zone || deal.region}</small></td><td>{deal.assigned_to || "Unassigned"}</td><td><b>{money(deal.potential_value || deal.value)}</b></td><td>{money(Number(deal.potential_value || deal.value) * Number(deal.probability || 0) / 100)}</td><td>{progress(deal)}<small className="crmStageLabel">{deal.stage}</small></td><td>{deal.next_action || "—"}</td><td>{deal.next_follow_up || "Not set"}</td><td><button className="crmEdit" onClick={() => startVisit(deal, "General follow-up")}>Log update</button></td></tr>)}</tbody></table></div>
      : tab === "quotes" ? <div className="tablewrap"><table><thead><tr><th>Customer</th><th>Quote</th><th>Date Issued</th><th>Value</th><th>Status</th><th>Last Follow-up</th><th>Next Follow-up</th><th>Age / Alert</th><th>Rep</th><th>Actions</th></tr></thead><tbody>{deals.filter((deal) => deal.quotation_no || ["Quotation", "Follow-up", "Negotiation"].includes(deal.stage)).map((deal) => <tr key={deal.id} className={quoteOverdue(deal) ? "crmOverdueRow" : ""}><td><b>{deal.customer_name}</b></td><td><b>{deal.quotation_no || "Number pending"}</b></td><td>{deal.quote_date || "Not set"}</td><td>{money(deal.potential_value || deal.value)}</td><td>{deal.quote_status || "Pending"}</td><td>{deal.quote_follow_up_date || "No follow-up"}</td><td>{deal.next_follow_up || "Not set"}</td><td>{alertBadge("quote", deal)}<small>{deal.quote_date ? `${ageInDays(deal.quote_date)} days since quote` : "Quote date required"}</small></td><td>{deal.assigned_to || "Unassigned"}</td><td><button className="crmEdit" onClick={() => startVisit(deal, "Quote follow-up")}>Log follow-up</button></td></tr>)}</tbody></table></div>
      : tab === "deliveries" ? <div className="tablewrap"><table><thead><tr><th>Customer</th><th>Order / Invoice</th><th>Confirmed</th><th>Order Value</th><th>Delivery Status</th><th>Planned ETA</th><th>Days Waiting</th><th>Alert</th><th>Notes</th><th>Actions</th></tr></thead><tbody>{deals.filter((deal) => deal.order_no || deal.invoice_no || ["Confirmed Order", "Invoiced", "Delivery Planned", "Delivered"].includes(deal.stage)).map((deal) => <tr key={deal.id} className={deliveryOverdue(deal) ? "crmOverdueRow" : ""}><td><b>{deal.customer_name}</b></td><td>{deal.order_no || "—"}<small>{deal.invoice_no || "No invoice number"}</small></td><td>{deal.confirmed_date || "Not set"}</td><td><b>{money(deal.value)}</b></td><td>{deal.delivery_status || "Not planned"}</td><td>{deal.delivery_eta || "Not set"}</td><td>{deal.confirmed_date ? ageInDays(deal.confirmed_date) : "—"}</td><td>{alertBadge("delivery", deal)}</td><td className="crmNotesCell">{deal.delivery_notes || "—"}</td><td><button className="crmEdit" onClick={() => startVisit(deal, "Order / delivery update")}>Log update</button></td></tr>)}</tbody></table></div>
      : <><div className="commissionHead"><span><small>HEAD OF WHOLESALE</small><b>{wholesaleHead}</b><em>Wholesale division owner</em></span><p>Commission is calculated from confirmed sales and gross profit. Sales reps and coordinators are selected from your Hub members on each customer record.</p></div><div className="commissionRules"><span><small>Monthly sales target</small><b>{money(settings.base_target)}</b></span><span><small>Standard rep commission</small><b>{settings.rep_base_rate}% of GP when GP is {settings.base_gp_threshold}%+</b></span><span><small>Higher GP reward</small><b>{settings.rep_accelerator_rate}% of GP when GP is {settings.accelerator_gp_threshold}%+</b></span><span><small>Support commission</small><b>Coordinator {settings.coordinator_rate}% · Wholesale Head {settings.head_rate}% of GP</b></span></div><div className="tablewrap"><table><thead><tr><th>Sales Rep</th><th>Coordinator</th><th>Customers / Visits</th><th>Quotes / Orders</th><th>Confirmed Sales</th><th>Gross Profit</th><th>Target Progress</th><th>Sales Rep Commission</th><th>Coordinator Commission</th><th>Wholesale Head Commission</th></tr></thead><tbody>{performance.map((row) => <tr key={row.rep}><td><b>{row.rep}</b></td><td>{row.coordinator}</td><td>{row.customers} / {row.visits}</td><td>{row.quotes} / {row.orders}</td><td><b>{money(row.sales)}</b></td><td>{money(row.gp)}<small>{row.gpp.toFixed(1)}% GP</small></td><td><span className="targetProgress"><i style={{ width: `${Math.min(100, row.sales / Math.max(1, row.target) * 100)}%` }} /></span><small>{Math.round(row.sales / Math.max(1, row.target) * 100)}% of {money(row.target)}</small></td><td><b>{money(row.repCommission)}</b><small>{row.eligible ? `${row.rate}% of gross profit` : "Sales target not reached"}</small></td><td>{money(row.coordinatorCommission)}</td><td>{money(row.headCommission)}<small>{wholesaleHead}</small></td></tr>)}</tbody></table></div></>}
    </section>

    {openDeal && <div className="overlay" onMouseDown={() => setOpenDeal(false)}><div className="crmModal wholesaleDealModal enrolmentModal" onMouseDown={(event) => event.stopPropagation()}><header><span><small>CUSTOMER ENROLMENT &amp; APPROVAL</small><h2>{editing ? `${dealDraft.customer_number || "Pending"} · ${dealDraft.customer_name}` : "New wholesale customer application"}</h2><p>Complete the intake, attach supporting documents and submit it for Head of Wholesale approval.</p></span><button onClick={() => setOpenDeal(false)}>×</button></header><div className="enrolmentSteps">{[[1,"Business"],[2,"People & Delivery"],[3,"Buying Profile"],[4,"Documents & Submit"]].map(([step,label]) => <button key={step} className={enrolmentStep === step ? "active" : enrolmentStep > Number(step) ? "done" : ""} onClick={() => setEnrolmentStep(Number(step))}><i>{enrolmentStep > Number(step) ? "✓" : step}</i><span>{label}</span></button>)}</div>{error && <div className="formError">{error}</div>}<div className="enrolmentBody">
      {enrolmentStep === 1 && <section><h3>Business information</h3><p>Customer category and registered business details from the enrolment form.</p><div className="crmForm enrolmentGrid"><label>Trading Name *<input value={dealDraft.customer_name} onChange={(event) => setDealDraft({ ...dealDraft, customer_name: event.target.value })} /></label><label>Registered Business Name<input value={dealDraft.registered_name} onChange={(event) => setDealDraft({ ...dealDraft, registered_name: event.target.value })} /></label><label>Customer Category<select value={dealDraft.customer_type} onChange={(event) => setDealDraft({ ...dealDraft, customer_type: event.target.value })}>{customerTypes.map((type) => <option key={type}>{type}</option>)}</select></label><label>Company / Registration No.<input value={dealDraft.registration_number} onChange={(event) => setDealDraft({ ...dealDraft, registration_number: event.target.value })} /></label><label>VAT Number<input value={dealDraft.vat_number} onChange={(event) => setDealDraft({ ...dealDraft, vat_number: event.target.value })} /></label><label>Legal Entity<select value={dealDraft.legal_entity} onChange={(event) => setDealDraft({ ...dealDraft, legal_entity: event.target.value })}>{["Sole Proprietor", "Partnership", "(Pty) Ltd", "CC", "Other"].map((option) => <option key={option}>{option}</option>)}</select></label><label>Business Type<select value={dealDraft.nature_of_business} onChange={(event) => setDealDraft({ ...dealDraft, nature_of_business: event.target.value })}>{["Hardware Store", "Building Materials Retailer", "Paint Store", "Plumbing / Sanware", "Other"].map((option) => <option key={option}>{option}</option>)}</select></label><label>Years in Business<input type="number" value={dealDraft.years_in_business} onChange={(event) => setDealDraft({ ...dealDraft, years_in_business: event.target.value })} /></label><label>Number of Branches<input type="number" value={dealDraft.branch_count} onChange={(event) => setDealDraft({ ...dealDraft, branch_count: event.target.value })} /></label><label className="wide">Head-office / Business Address<textarea value={dealDraft.head_office_address} onChange={(event) => setDealDraft({ ...dealDraft, head_office_address: event.target.value })} /></label><label>Province<input value={dealDraft.province} onChange={(event) => setDealDraft({ ...dealDraft, province: event.target.value })} /></label><label>Region<input value={dealDraft.region} onChange={(event) => setDealDraft({ ...dealDraft, region: event.target.value })} /></label><label>Zone / Area<input value={dealDraft.zone} onChange={(event) => setDealDraft({ ...dealDraft, zone: event.target.value })} /></label><label>Postal Code<input value={dealDraft.postal_code} onChange={(event) => setDealDraft({ ...dealDraft, postal_code: event.target.value })} /></label><label>Business Telephone<input value={dealDraft.contact} onChange={(event) => setDealDraft({ ...dealDraft, contact: event.target.value })} /></label><label>Business Email<input type="email" value={dealDraft.email} onChange={(event) => setDealDraft({ ...dealDraft, email: event.target.value })} /></label><label>Website / Social Media<input value={dealDraft.website} onChange={(event) => setDealDraft({ ...dealDraft, website: event.target.value })} /></label></div></section>}
      {enrolmentStep === 2 && <><section><h3>Owner / director information</h3><div className="crmForm enrolmentGrid"><label>Owner / Director 1<input value={dealDraft.owner1_name} onChange={(event) => setDealDraft({ ...dealDraft, owner1_name: event.target.value })} /></label><label>ID / Passport No.<input value={dealDraft.owner1_id} onChange={(event) => setDealDraft({ ...dealDraft, owner1_id: event.target.value })} /></label><label>Position<input value={dealDraft.owner1_position} onChange={(event) => setDealDraft({ ...dealDraft, owner1_position: event.target.value })} /></label><label>Mobile<input value={dealDraft.owner1_mobile} onChange={(event) => setDealDraft({ ...dealDraft, owner1_mobile: event.target.value })} /></label><label>Owner / Director 2<input value={dealDraft.owner2_name} onChange={(event) => setDealDraft({ ...dealDraft, owner2_name: event.target.value })} /></label><label>ID / Passport No.<input value={dealDraft.owner2_id} onChange={(event) => setDealDraft({ ...dealDraft, owner2_id: event.target.value })} /></label><label>Position<input value={dealDraft.owner2_position} onChange={(event) => setDealDraft({ ...dealDraft, owner2_position: event.target.value })} /></label><label>Mobile<input value={dealDraft.owner2_mobile} onChange={(event) => setDealDraft({ ...dealDraft, owner2_mobile: event.target.value })} /></label></div></section><section><h3>Purchasing and accounts contacts</h3><div className="crmForm enrolmentGrid"><label>Primary / Purchasing Contact<input value={dealDraft.purchasing_contact_name} onChange={(event) => setDealDraft({ ...dealDraft, purchasing_contact_name: event.target.value, contact_person: event.target.value })} /></label><label>Purchasing Mobile<input value={dealDraft.purchasing_contact_mobile} onChange={(event) => setDealDraft({ ...dealDraft, purchasing_contact_mobile: event.target.value })} /></label><label>Purchasing Email<input type="email" value={dealDraft.purchasing_contact_email} onChange={(event) => setDealDraft({ ...dealDraft, purchasing_contact_email: event.target.value })} /></label><label>Accounts / Finance Contact<input value={dealDraft.accounts_contact_name} onChange={(event) => setDealDraft({ ...dealDraft, accounts_contact_name: event.target.value })} /></label><label>Accounts Mobile<input value={dealDraft.accounts_contact_mobile} onChange={(event) => setDealDraft({ ...dealDraft, accounts_contact_mobile: event.target.value })} /></label><label>Accounts Email<input type="email" value={dealDraft.accounts_contact_email} onChange={(event) => setDealDraft({ ...dealDraft, accounts_contact_email: event.target.value })} /></label></div></section><section><h3>Delivery information</h3><div className="crmForm enrolmentGrid"><label className="wide">Delivery Address<textarea value={dealDraft.delivery_address} onChange={(event) => setDealDraft({ ...dealDraft, delivery_address: event.target.value })} /></label><label>Delivery Contact<input value={dealDraft.delivery_contact} onChange={(event) => setDealDraft({ ...dealDraft, delivery_contact: event.target.value })} /></label><label>Delivery Contact Mobile<input value={dealDraft.delivery_contact_mobile} onChange={(event) => setDealDraft({ ...dealDraft, delivery_contact_mobile: event.target.value })} /></label><label>Receiving Hours<input value={dealDraft.receiving_hours} onChange={(event) => setDealDraft({ ...dealDraft, receiving_hours: event.target.value })} placeholder="Example: Mon–Fri 08:00–15:00" /></label><label className="wide">Delivery / Offloading Requirements<textarea value={dealDraft.delivery_requirements} onChange={(event) => setDealDraft({ ...dealDraft, delivery_requirements: event.target.value })} placeholder="Vehicle access, forklift, offloading restrictions or directions" /></label></div></section></>}
      {enrolmentStep === 3 && <><section><h3>Customer purchasing profile</h3><p>Select every category the customer buys.</p><div className="productCategoryGrid">{productCategories.map((product) => <label key={product} className={selectedProducts.includes(product) ? "selected" : ""}><input type="checkbox" checked={selectedProducts.includes(product)} onChange={() => toggleProduct(product)} />{product}</label>)}</div><div className="crmForm enrolmentGrid"><label>Average Monthly Spend (R)<input type="number" value={dealDraft.average_monthly_spend} onChange={(event) => setDealDraft({ ...dealDraft, average_monthly_spend: event.target.value, potential_value: event.target.value })} /></label><label>Ordering Method<select value={dealDraft.ordering_method} onChange={(event) => setDealDraft({ ...dealDraft, ordering_method: event.target.value })}>{["WhatsApp / Email", "Telephone", "Sales Rep", "Online", "In Store"].map((option) => <option key={option}>{option}</option>)}</select></label><label>Ordering Frequency<select value={dealDraft.ordering_frequency} onChange={(event) => setDealDraft({ ...dealDraft, ordering_frequency: event.target.value })}>{["Daily", "Weekly", "Fortnightly", "Monthly", "As required"].map((option) => <option key={option}>{option}</option>)}</select></label><label>Payment Terms<select value={dealDraft.payment_terms} onChange={(event) => setDealDraft({ ...dealDraft, payment_terms: event.target.value, credit_requested: event.target.value === "Credit Account" ? "1" : "0" })}>{["COD / EFT Before Dispatch", "Cash / Card", "Credit Account"].map((option) => <option key={option}>{option}</option>)}</select><small>Credit accounts require a separate credit application and approval.</small></label><label>Price Group<select value={dealDraft.price_group} onChange={(event) => setDealDraft({ ...dealDraft, price_group: event.target.value })}>{["Standard Wholesale", "Small Hardware", "Medium Hardware", "Large Hardware", "Special Pricing Review"].map((option) => <option key={option}>{option}</option>)}</select></label><label>Assigned Sales Rep<select value={dealDraft.assigned_to} onChange={(event) => setDealDraft({ ...dealDraft, assigned_to: event.target.value })}><option value="">Select a Hub member</option>{memberOptions(dealDraft.assigned_to).map((name) => <option key={name}>{name}</option>)}</select></label><label>Wholesale Coordinator<select value={dealDraft.coordinator} onChange={(event) => setDealDraft({ ...dealDraft, coordinator: event.target.value })}><option value="">Select a Hub member</option>{memberOptions(dealDraft.coordinator).map((name) => <option key={name}>{name}</option>)}</select></label><label>Monthly Rep Target (R)<input type="number" value={dealDraft.monthly_target} onChange={(event) => setDealDraft({ ...dealDraft, monthly_target: event.target.value })} /></label><label className="wide">Internal Notes / Special Pricing<input value={dealDraft.approval_comments} onChange={(event) => setDealDraft({ ...dealDraft, approval_comments: event.target.value })} /></label></div></section></>}
      {enrolmentStep === 4 && <><section><h3>Required documents and business pictures</h3><p>Upload registration documents, VAT certificate, owner IDs, proof of address and store or yard pictures. Maximum 15MB per file.</p><div className="customerUploadBox"><select value={uploadDocumentType} onChange={(event) => setUploadDocumentType(event.target.value)}>{documentTypes.map((type) => <option key={type}>{type}</option>)}</select><label><input type="file" multiple accept="image/*,.pdf,.doc,.docx,.xls,.xlsx" onChange={(event) => { const files = Array.from(event.target.files || []); setCustomerFiles((current) => [...current, ...files.map((file) => ({ file, type: uploadDocumentType }))]); event.target.value = ""; }} />＋ Choose documents or pictures</label></div>{customerFiles.length > 0 && <div className="customerFileList">{customerFiles.map((upload, index) => <span key={`${upload.file.name}-${index}`}><i>{upload.file.type.startsWith("image/") ? "PHOTO" : "FILE"}</i><b>{upload.file.name}</b><small>{upload.type}</small><button onClick={() => setCustomerFiles((current) => current.filter((_, itemIndex) => itemIndex !== index))}>×</button></span>)}</div>}{existingDocuments.length > 0 && <div className="customerFileList existing">{existingDocuments.map((document) => <a key={document.id} href={`/api/wholesale/documents/${document.id}`} target="_blank" rel="noreferrer"><i>{document.mime_type.startsWith("image/") ? "PHOTO" : "FILE"}</i><b>{document.name}</b><small>{document.document_type} · uploaded by {document.uploaded_by}</small></a>)}</div>}</section><section className="customerDeclaration"><h3>Customer declaration</h3><p>I confirm that the information supplied is true and correct. I understand that completing this customer-enrolment form does not constitute credit approval. Any credit facility requires a separate application, assessment and approval.</p><label><input type="checkbox" checked={dealDraft.declaration_accepted === "1"} onChange={(event) => setDealDraft({ ...dealDraft, declaration_accepted: event.target.checked ? "1" : "0" })} /> Declaration accepted and confirmed by the customer / representative.</label></section><section className="approvalFlow"><h3>Internal approval route</h3><div><span><i>1</i><b>Sales Representative</b><small>Captures and submits</small></span><span><i>2</i><b>Wholesale Coordinator</b><small>Checks completeness</small></span><span><i>3</i><b>Head of Wholesale</b><small>{wholesaleHead} approves</small></span><span><i>4</i><b>Accounts / Finance</b><small>Activates COD or separate credit</small></span></div><p>The sequential customer account number is generated only after approval.</p></section></>}
    </div><footer><button onClick={() => setOpenDeal(false)}>Cancel</button>{enrolmentStep > 1 && <button onClick={() => setEnrolmentStep((step) => step - 1)}>Back</button>}{enrolmentStep < 4 ? <button className="primary" onClick={() => setEnrolmentStep((step) => step + 1)}>Continue</button> : <button className="primary" disabled={saving || dealDraft.declaration_accepted !== "1"} onClick={() => void saveDeal()}>{saving ? "Submitting application…" : editing ? "Save enrolment changes" : "Submit for approval"}</button>}</footer></div></div>}

    {openVisit && <div className="overlay" onMouseDown={() => setOpenVisit(false)}><div className="crmModal visitModal quickUpdateModal" onMouseDown={(event) => event.stopPropagation()}><header><span><small>{visitDraft.visit_status === "Planned" ? "REP VISIT PLANNER" : "ONE-STEP CRM ACTIVITY"}</small><h2>{visitDraft.visit_status === "Planned" ? "Schedule customer visit" : editingVisit ? "Complete planned visit" : "Log customer update"}</h2><p>{visitDraft.visit_status === "Planned" ? "Build the rep's itinerary with the customer, area, time and purpose before they leave." : "Complete the visit once and the customer, pipeline, quote and order views update automatically."}</p></span><button onClick={() => setOpenVisit(false)}>×</button></header>{error && <div className="formError">{error}</div>}<div className="quickUpdateForm">
      <section><h3>{visitDraft.visit_status === "Planned" ? "Visit plan" : "Visit or contact result"}</h3><div className="crmForm"><label>Customer<select value={visitDraft.opportunity_id} onChange={(event) => selectVisitCustomer(event.target.value)} disabled={Boolean(editingVisit)}><option value="">Select customer</option>{deals.filter((deal) => deal.application_status === "Approved" || Boolean(deal.customer_number)).map((deal) => <option key={deal.id} value={deal.id}>{deal.customer_number || "Pending"} · {deal.customer_name} · {deal.assigned_to || "Unassigned"}</option>)}</select></label><label>Activity Type<select value={visitDraft.update_type} onChange={(event) => setVisitDraft({ ...visitDraft, update_type: event.target.value, visit_status: event.target.value === "Customer visit" ? visitDraft.visit_status : "Completed" })}>{["Customer visit", "General follow-up", "Quote follow-up", "Order / delivery update"].map((type) => <option key={type}>{type}</option>)}</select></label><label>Status<select value={visitDraft.visit_status} onChange={(event) => setVisitDraft({ ...visitDraft, visit_status: event.target.value })}>{["Planned", "Completed", "Cancelled", "Rescheduled"].map((status) => <option key={status}>{status}</option>)}</select></label><label>Date<input type="date" value={visitDraft.visit_date} onChange={(event) => setVisitDraft({ ...visitDraft, visit_date: event.target.value })} /></label><label>Time<input type="time" value={visitDraft.scheduled_time} onChange={(event) => setVisitDraft({ ...visitDraft, scheduled_time: event.target.value })} /></label><label>Purpose<select value={visitDraft.purpose} onChange={(event) => setVisitDraft({ ...visitDraft, purpose: event.target.value })}>{["New customer prospect", "Relationship visit", "Product presentation", "Quote follow-up", "Order follow-up", "Payment / account query", "Complaint resolution", "Merchandising / stock review"].map((purpose) => <option key={purpose}>{purpose}</option>)}</select></label><label>Area / Route<input value={visitDraft.area} onChange={(event) => setVisitDraft({ ...visitDraft, area: event.target.value })} /></label><label className="wide">Visit Address<input value={visitDraft.visit_address} onChange={(event) => setVisitDraft({ ...visitDraft, visit_address: event.target.value })} /></label><label>Contact Method<select value={visitDraft.visit_type} onChange={(event) => setVisitDraft({ ...visitDraft, visit_type: event.target.value })}>{["In person", "Telephone", "WhatsApp", "Email", "Video call"].map((type) => <option key={type}>{type}</option>)}</select></label><label>Contact Person<input value={visitDraft.contact_person} onChange={(event) => setVisitDraft({ ...visitDraft, contact_person: event.target.value })} /></label>{visitDraft.visit_status !== "Planned" && <><label>Next Follow-up<input type="date" value={visitDraft.next_follow_up} onChange={(event) => setVisitDraft({ ...visitDraft, next_follow_up: event.target.value })} /></label><label className="wide">Outcome / Next Action<input value={visitDraft.outcome} onChange={(event) => setVisitDraft({ ...visitDraft, outcome: event.target.value })} placeholder="Example: Customer requested revised quote" /></label><label className="wide">Visit Notes<textarea value={visitDraft.notes} onChange={(event) => setVisitDraft({ ...visitDraft, notes: event.target.value })} /></label></>}</div></section>
      {visitDraft.update_type === "Quote follow-up" ? <section className="quickLinkedSection"><h3>Quote update</h3><p>This will appear automatically under Quotes &amp; Follow-ups.</p><div className="crmForm"><label>Quote Number<input value={visitDraft.quotation_no} onChange={(event) => setVisitDraft({ ...visitDraft, quotation_no: event.target.value })} /></label><label>Quote Status<select value={visitDraft.quote_status} onChange={(event) => setVisitDraft({ ...visitDraft, quote_status: event.target.value })}>{["Pending", "Follow-up required", "Revised", "Accepted", "Declined"].map((status) => <option key={status}>{status}</option>)}</select></label><label>Sales Potential (R)<input type="number" value={visitDraft.potential_value} onChange={(event) => setVisitDraft({ ...visitDraft, potential_value: event.target.value })} /></label><label>Pipeline Stage<select value={visitDraft.stage} onChange={(event) => setVisitDraft({ ...visitDraft, stage: event.target.value })}>{["Quotation", "Follow-up", "Negotiation", "Confirmed Order", "Lost"].map((stage) => <option key={stage}>{stage}</option>)}</select></label></div></section>
      : visitDraft.update_type === "Order / delivery update" ? <section className="quickLinkedSection"><h3>Order and delivery update</h3><p>This will appear automatically under Orders &amp; Deliveries.</p><div className="crmForm"><label>Order Number<input value={visitDraft.order_no} onChange={(event) => setVisitDraft({ ...visitDraft, order_no: event.target.value })} /></label><label>Invoice Number<input value={visitDraft.invoice_no} onChange={(event) => setVisitDraft({ ...visitDraft, invoice_no: event.target.value })} /></label><label>Confirmed Value (R)<input type="number" value={visitDraft.value} onChange={(event) => setVisitDraft({ ...visitDraft, value: event.target.value })} /></label><label>Delivery Status<select value={visitDraft.delivery_status} onChange={(event) => setVisitDraft({ ...visitDraft, delivery_status: event.target.value })}>{["Not planned", "Planned", "Picking", "Ready to dispatch", "Dispatched", "Delivered"].map((status) => <option key={status}>{status}</option>)}</select></label><label>Delivery ETA<input type="date" value={visitDraft.delivery_eta} onChange={(event) => setVisitDraft({ ...visitDraft, delivery_eta: event.target.value })} /></label><label>Pipeline Stage<select value={visitDraft.stage} onChange={(event) => setVisitDraft({ ...visitDraft, stage: event.target.value })}>{["Confirmed Order", "Invoiced", "Delivery Planned", "Delivered"].map((stage) => <option key={stage}>{stage}</option>)}</select></label></div></section>
      : visitDraft.visit_status === "Completed" ? <section className="quickLinkedSection compact"><h3>Sales progress</h3><p>Only adjust these when the visit moved the opportunity forward.</p><div className="crmForm"><label>Pipeline Stage<select value={visitDraft.stage} onChange={(event) => setVisitDraft({ ...visitDraft, stage: event.target.value })}>{stages.map((stage) => <option key={stage}>{stage}</option>)}</select></label><label>Sales Potential (R)<input type="number" value={visitDraft.potential_value} onChange={(event) => setVisitDraft({ ...visitDraft, potential_value: event.target.value })} /></label><label>Probability %<input type="number" value={visitDraft.probability} onChange={(event) => setVisitDraft({ ...visitDraft, probability: event.target.value })} /></label></div></section> : null}
    </div><footer><button onClick={() => setOpenVisit(false)}>Cancel</button><button className="primary" disabled={saving} onClick={() => void saveVisit()}>{saving ? "Saving…" : visitDraft.visit_status === "Planned" ? "Add to visit planner" : "Save completed visit"}</button></footer></div></div>}

    {approvalDeal && <div className="overlay" onMouseDown={() => setApprovalDeal(null)}><div className="crmModal approvalModal" onMouseDown={(event) => event.stopPropagation()}><header><span><small>HEAD OF WHOLESALE REVIEW</small><h2>{approvalDeal.customer_name}</h2><p>Review the enrolment, supporting documents and declaration before issuing a customer number.</p></span><button onClick={() => setApprovalDeal(null)}>×</button></header>{error && <div className="formError">{error}</div>}<div className="approvalSummary"><span><small>Current Status</small><b>{approvalDeal.application_status || "Pending approval"}</b></span><span><small>Assigned Rep</small><b>{approvalDeal.assigned_to || "Not assigned"}</b></span><span><small>Documents</small><b>{approvalDeal.document_count || 0} uploaded</b></span><span><small>Payment</small><b>{approvalDeal.payment_terms || "COD"}</b></span></div><div className="approvalBusiness"><span><small>Registered Business</small><b>{approvalDeal.registered_name || approvalDeal.customer_name}</b><em>{approvalDeal.registration_number || "Registration number not supplied"} · VAT {approvalDeal.vat_number || "not supplied"}</em></span><span><small>Owner / Director</small><b>{approvalDeal.owner1_name || "Not supplied"}</b><em>{approvalDeal.owner1_mobile || "No mobile"}</em></span><span><small>Purchasing Contact</small><b>{approvalDeal.purchasing_contact_name || approvalDeal.contact_person || "Not supplied"}</b><em>{approvalDeal.purchasing_contact_mobile || approvalDeal.contact || "No mobile"}</em></span><span><small>Buying Profile</small><b>{money(approvalDeal.average_monthly_spend)} monthly</b><em>{approvalDeal.customer_type} · {approvalDeal.price_group}</em></span></div>{existingDocuments.length > 0 ? <div className="customerFileList existing">{existingDocuments.map((document) => <a key={document.id} href={`/api/wholesale/documents/${document.id}`} target="_blank" rel="noreferrer"><i>{document.mime_type.startsWith("image/") ? "PHOTO" : "FILE"}</i><b>{document.name}</b><small>{document.document_type}</small></a>)}</div> : <p className="approvalWarning">No supporting documents have been uploaded yet.</p>}<button className="viewApplication" onClick={() => { const deal = approvalDeal; setApprovalDeal(null); startDeal(deal); }}>Open full customer application</button><label className="approvalNotes">Review Comments<textarea value={approvalComments} onChange={(event) => setApprovalComments(event.target.value)} placeholder="Record approval conditions, missing information or the reason for declining." /></label><footer><button disabled={saving} onClick={() => void approveCustomer("Decline")}>Decline</button><button disabled={saving} onClick={() => void approveCustomer("Request changes")}>Request changes</button><button className="primary" disabled={saving} onClick={() => void approveCustomer("Approve")}>{saving ? "Approving…" : "Approve & issue customer number"}</button></footer></div></div>}

    {settingsOpen && <div className="overlay" onMouseDown={() => setSettingsOpen(false)}><div className="crmModal commissionModal" onMouseDown={(event) => event.stopPropagation()}><header><span><h2>Commission rules</h2><p>Set the target and the percentage of gross profit paid at each level.</p></span><button onClick={() => setSettingsOpen(false)}>×</button></header><div className="crmForm">{[
      ["Monthly sales target per rep (R)", "base_target", "Commission starts once the rep reaches this sales value."],
      ["Minimum gross profit %", "base_gp_threshold", "The minimum GP percentage required for standard commission."],
      ["Standard sales rep commission (% of GP)", "rep_base_rate", "The rep's share of gross profit at the standard level."],
      ["Higher gross profit reward starts at (%)", "accelerator_gp_threshold", "The GP percentage that unlocks the higher rep reward."],
      ["Higher sales rep commission (% of GP)", "rep_accelerator_rate", "The rep's share of gross profit when the higher level is reached."],
      ["Sales coordinator commission (% of GP)", "coordinator_rate", "The coordinator's share of gross profit."],
      ["Head of Wholesale commission (% of GP)", "head_rate", `${wholesaleHead}'s share of gross profit.`],
    ].map(([label, key, help]) => <label key={key}>{label}<input type="number" value={settings[key as keyof Settings]} onChange={(event) => setSettings({ ...settings, [key]: Number(event.target.value) })} /><small>{help}</small></label>)}</div><footer><button onClick={() => setSettingsOpen(false)}>Cancel</button><button className="primary" disabled={saving} onClick={() => void saveSettings()}>Save commission rules</button></footer></div></div>}
  </>;
}
